// ------------------------------------------------------------------ บทที่ 2
function ch2() {
  return [
    ...chapter(2, 'เอกสารและงานวิจัยที่เกี่ยวข้อง'),
    H2('2.1', 'แผ่นดินทรุดและสาเหตุ'),
    P('แผ่นดินทรุด (land subsidence) คือการลดระดับของผิวดินเทียบกับระดับอ้างอิง สาเหตุหลักในที่ราบตะกอนคือการสูบน้ำใต้ดินเกินอัตราการเติม ทำให้แรงดันน้ำในช่องว่างของดินลดลง หน่วยแรงประสิทธิผลเพิ่มขึ้น และชั้นดินเหนียวที่สลับกับชั้นน้ำบาดาลยุบอัดตัว การยุบอัดของดินเหนียวส่วนใหญ่เป็นแบบคืนกลับไม่ได้ แม้ระดับน้ำบาดาลจะฟื้นตัวแล้ว (Galloway & Burbey, 2011) Herrera-García et al. (2021) ประเมินว่าประชากรโลกราวร้อยละ 19 อาจได้รับผลกระทบจากแผ่นดินทรุดภายในปี 2583 โดยเฉพาะเมืองบนดินดอนสามเหลี่ยมปากแม่น้ำในเอเชีย'),
    P('ผลกระทบของแผ่นดินทรุดแบ่งเป็นสองกลุ่ม กลุ่มแรกคือผลต่อสิ่งก่อสร้างจากการทรุดไม่เท่ากัน (differential settlement) เช่น อาคารร้าว ท่อแตก ถนนและรางเสียระดับ กลุ่มที่สองคือการเพิ่มความเสี่ยงน้ำท่วม เพราะพื้นดินต่ำลง ระบบระบายน้ำด้วยแรงโน้มถ่วงทำงานได้น้อยลง และคันกั้นน้ำทรุดตามพื้นดิน'),
    H2('2.2', 'แผ่นดินทรุดในกรุงเทพมหานครและปริมณฑล'),
    P('Phien-wej et al. (2006) สรุปว่าการทรุดในกรุงเทพฯ เกิดจากการสูบน้ำบาดาลจากชั้นน้ำกรุงเทพ พระประแดง และนครหลวง อัตราการทรุดในเขตชั้นในลดลงหลังมาตรการควบคุมน้ำบาดาลตั้งแต่ทศวรรษ 2520–2540 แต่พื้นที่ทรุดเร็วเคลื่อนออกไปยังชานเมืองด้านตะวันออกและตะวันตกเฉียงใต้ที่มีโรงงานและหมู่บ้านจัดสรรเพิ่มขึ้น Aobpaet et al. (2013) ใช้อนุกรมเวลา InSAR จากดาวเทียม ALOS และ ENVISAT พบการทรุดสูงสุดราว 20–30 มม./ปี ทางตะวันออกและตะวันตกเฉียงใต้ของกรุงเทพฯ ส่วน Tay et al. (2022) วิเคราะห์เมืองชายฝั่ง 48 แห่งด้วย Sentinel-1 พบว่ากรุงเทพฯ อยู่ในกลุ่มที่การทรุดเป็นส่วนสำคัญของระดับน้ำทะเลสัมพัทธ์ที่เพิ่มขึ้น'),
    H2('2.3', 'เรดาร์ช่องเปิดสังเคราะห์และอินเทอร์เฟอโรเมตรี (InSAR)'),
    P('เรดาร์ช่องเปิดสังเคราะห์ (SAR) ส่งคลื่นไมโครเวฟและบันทึกทั้งความเข้มและเฟสของสัญญาณสะท้อน จึงถ่ายภาพได้ทั้งกลางวันและกลางคืนและทะลุเมฆได้ เมื่อถ่ายพื้นที่เดียวกันจากตำแหน่งวงโคจรใกล้เคียงสองครั้ง ผลต่างเฟส (Δφ) ของสองภาพจะสัมพันธ์กับการเปลี่ยนระยะทางในแนว LOS (Hanssen, 2001) ดังสมการ'),
    eq('d_LOS = −(λ / 4π) · Δφ'),
    P('เมื่อ λ คือความยาวคลื่น ซึ่งสำหรับ Sentinel-1 (ย่าน C) เท่ากับประมาณ 5.55 ซม. ดังนั้นเฟสหนึ่งรอบ (2π) เท่ากับการเคลื่อนตัวราว 2.8 ซม. ในแนว LOS นอกจากการเคลื่อนตัว เฟสยังมีส่วนจากวงโคจร ภูมิประเทศ ความหน่วงของชั้นบรรยากาศ และสัญญาณรบกวน การวิเคราะห์จึงต้องแยกส่วนเหล่านี้ออก'),
    P('ดาวเทียม Sentinel-1 ของโครงการ Copernicus ถ่ายภาพในโหมด Interferometric Wide swath (IW) ด้วยเทคนิค TOPS แบ่งภาพเป็น sub-swath และ burst ย่อย (Torres et al., 2012) การต่อ burst ต้องจัดภาพให้ตรงกันละเอียดมากในแนว azimuth ด้วยวิธี Enhanced Spectral Diversity (ESD) มิฉะนั้นจะเกิดรอยต่อเฟสที่ขอบ burst (Yagüe-Martínez et al., 2016)'),
    H2('2.4', 'อนุกรมเวลา SBAS และซอฟต์แวร์ MintPy'),
    P('วิธี Small Baseline Subset (SBAS) ของ Berardino et al. (2002) สร้าง interferogram จากคู่ภาพที่มีเส้นฐานเชิงเวลาและเชิงพื้นที่สั้นจำนวนมาก แล้วแก้ระบบสมการด้วยกำลังสองน้อยที่สุดเพื่อหาการเคลื่อนตัวสะสม ณ แต่ละวันที่ถ่ายภาพ ช่วยลดผลของการสูญเสียความสัมพันธ์ (decorrelation) และเฉลี่ยสัญญาณรบกวนของชั้นบรรยากาศ ซอฟต์แวร์ MintPy (Yunjun et al., 2019) ใช้วิธีนี้ร่วมกับการแก้ความผิดพลาดในการคลี่เฟส (unwrapping error) การแก้ชั้นบรรยากาศด้วยข้อมูลแบบจำลองภูมิอากาศ ERA5 (Hersbach et al., 2020) และการประมาณความเร็วเชิงเส้นพร้อมความไม่แน่นอน'),
    H2('2.5', 'การแยกองค์ประกอบการเคลื่อนตัวจากสองวงโคจร'),
    P('ค่า LOS จากวงโคจรเดียวเป็นผลรวมของการเคลื่อนตัวสามทิศ หากมีทั้งวงโคจรขาขึ้น (ascending) และขาลง (descending) ซึ่งมองจากคนละด้าน จะแก้สมการหาองค์ประกอบแนวดิ่ง (U) และแนวตะวันออก–ตะวันตก (E) ได้ โดยละองค์ประกอบเหนือ–ใต้ซึ่งดาวเทียมวงโคจรขั้วโลกไวต่อทิศนี้น้อยมาก (Wright et al., 2004)'),
    eq('d_LOS,k = U · u_U,k + E · u_E,k ,   k ∈ {asc, desc}'),
    P('เมื่อ u_U,k และ u_E,k คือองค์ประกอบแนวดิ่งและแนวตะวันออกของเวกเตอร์หนึ่งหน่วยในแนว LOS ของวงโคจร k ซึ่งคำนวณจากมุมตกกระทบและมุมทิศของแต่ละ pixel'),
    H2('2.6', 'ระบบดาวเทียมนำทาง GNSS'),
    P('สถานี GNSS แบบต่อเนื่องให้ค่าพิกัดสามมิติรายวันที่ความถูกต้องระดับมิลลิเมตร จึงใช้เป็นจุดอ้างอิงและตรวจสอบผล InSAR ซึ่งวัดได้เฉพาะการเคลื่อนตัวสัมพัทธ์ Nevada Geodetic Laboratory (NGL) ประมวลผลข้อมูลจากสถานีทั่วโลกด้วยมาตรฐานเดียวกันและเผยแพร่อนุกรมเวลาในกรอบอ้างอิง IGS20 (Blewitt et al., 2018) ในพื้นที่ศึกษามีสถานี CUSV (จุฬาลงกรณ์มหาวิทยาลัย) และ KMIT (สถาบันเทคโนโลยีพระจอมเกล้าเจ้าคุณทหารลาดกระบัง)'),
    H2('2.7', 'การประเมินการสัมผัสภัยจากแผ่นดินทรุด'),
    P('Ohenhen et al. (2024) ประเมินเมืองชายฝั่งของสหรัฐอเมริกาโดยซ้อนแผนที่อัตราการทรุดจาก InSAR กับประชากร อาคาร และโครงสร้างพื้นฐาน นับจำนวนที่อยู่ในพื้นที่ที่ทรุดเร็วกว่าเกณฑ์ต่าง ๆ (เช่น 2, 5, 10 มม./ปี) และคิดขอบล่าง–ขอบบนจากค่าความไม่แน่นอนของความเร็ว นอกจากนี้ยังใช้ angular distortion (β) ซึ่งเป็นตัวชี้วัดความเสียหายของอาคารจากการทรุดไม่เท่ากันตามแนวคิดของ Skempton และ MacDonald (1956)'),
    eq('β = |Δδ| / l'),
    P('เมื่อ Δδ คือผลต่างการทรุดสะสมระหว่างจุดข้างเคียง และ l คือระยะห่าง Cigna และ Tapete (2021) แบ่งระดับความเสียหายจาก β เป็น ต่ำ (< 1/3000) ปานกลาง (1/3000–1/1500) สูง (1/1500–1/500) และสูงมาก (≥ 1/500) ซึ่งโครงงานนี้ใช้เกณฑ์เดียวกัน'),
    H2('2.8', 'กรอบการประเมินความเสี่ยงและวงจรการจัดการภัยพิบัติ'),
    P('สำนักงานสหประชาชาติเพื่อการลดความเสี่ยงจากภัยพิบัติ (UNDRR, 2017) นิยามความเสี่ยงภัยพิบัติว่าขึ้นกับภัย (hazard) การสัมผัสภัย (exposure) ความเปราะบาง (vulnerability) และขีดความสามารถในการรับมือ นิยมเขียนเป็นความสัมพันธ์ ความเสี่ยง = ภัย × การสัมผัสภัย × ความเปราะบาง การจัดการภัยพิบัติแบ่งเป็นวงจร ได้แก่ การป้องกัน (prevention) การบรรเทา (mitigation) การเตรียมพร้อม (preparedness) การตอบสนอง (response) และการฟื้นฟู (recovery) ซึ่งโครงงานนี้ใช้จัดกลุ่มข้อเสนอแนะในบทที่ 5'),
    H2('2.9', 'การทำแผนที่น้ำท่วมด้วยภาพเรดาร์'),
    P('ผิวน้ำนิ่งสะท้อนคลื่นเรดาร์ออกไปทางอื่น ภาพ backscatter ในโพลาไรเซชัน VV จึงมืดกว่าพื้นดิน การตรวจหาน้ำท่วมนิยมใช้เกณฑ์ค่าความเข้มร่วมกับการเปลี่ยนแปลงจากภาพก่อนเกิดเหตุ (change detection) (Twele et al., 2016; UN-SPIDER, ม.ป.ป.) โดยหาเกณฑ์อัตโนมัติด้วยวิธีของ Otsu (1979) ที่แบ่ง histogram ออกเป็นสองกลุ่มให้ความแปรปรวนภายในกลุ่มต่ำที่สุด บริการ Global Flood Monitoring (GFM) ของ Copernicus ใช้หลักการคล้ายกันผลิตแผนที่น้ำท่วมอัตโนมัติทั่วโลก (Salamon et al., 2021)'),
    H2('2.10', 'ระดับน้ำทะเลที่สูงขึ้นและความสูงพื้นดินชายฝั่ง'),
    P('รายงาน IPCC AR6 คาดการณ์ระดับน้ำทะเลเฉลี่ยโลกที่ขึ้นกับฉากทัศน์ SSP และจัดทำค่าคาดการณ์รายสถานีวัดระดับน้ำ (Fox-Kemper et al., 2021; Garner et al., 2021) ค่าคาดการณ์ฉบับ “novlm” ไม่รวมการเคลื่อนตัวของแผ่นดินในพื้นที่ จึงต้องรวมการทรุดที่วัดได้เองเพื่อหาระดับน้ำทะเลสัมพัทธ์ Nicholls et al. (2021) แสดงว่าในเมืองบนดินดอนสามเหลี่ยม การทรุดทำให้ระดับน้ำทะเลสัมพัทธ์เพิ่มเร็วกว่าค่าเฉลี่ยโลกหลายเท่า'),
    P('การประเมินพื้นที่ต่ำต้องใช้แบบจำลองความสูงพื้นดินจริง (digital terrain model) ไม่ใช่ความสูงผิวบนสุดที่รวมอาคารและต้นไม้ DeltaDTM (Pronk et al., 2024) ปรับ Copernicus DEM ด้วยข้อมูล lidar จากดาวเทียม ICESat-2 และ GEDI ให้เป็นความสูงพื้นดินความละเอียด 30 เมตรตามแนวชายฝั่งทั่วโลก อ้างอิงพื้นผิว geoid EGM2008 (Pavlis et al., 2012) การแปลงเป็นความสูงเหนือระดับน้ำทะเลปานกลางทำได้ด้วยพื้นผิวทะเลเฉลี่ย DTU21 (Andersen et al., 2023) ส่วนระดับน้ำขึ้นสูงและคลื่นพายุใช้ผลจากแบบจำลอง Global Tide and Surge Model (GTSM) (Muis et al., 2020)'),
    H2('2.11', 'แบบจำลองน้ำท่วมชายฝั่ง SFINCS'),
    P('SFINCS (Super-Fast INundation of CoastS) พัฒนาโดย Deltares เป็นแบบจำลองชลศาสตร์สองมิติที่ใช้สมการน้ำตื้นแบบลดรูป (local inertia) จึงคำนวณได้เร็วพอสำหรับพื้นที่ขนาดใหญ่และฉากทัศน์จำนวนมาก โดยยังให้ผลใกล้เคียงแบบจำลองเต็มรูปในกรณีน้ำท่วมชายฝั่ง (Leijnse et al., 2021) แบบจำลองรองรับการกำหนดคันกั้นน้ำเป็นสันฝาย (weir) ซึ่งเหมาะกับการเปรียบเทียบกรณีมีและไม่มีคันกั้นน้ำ'),
    H2('2.12', 'แผ่นดินไหววันที่ 28 มีนาคม 2568'),
    P('แผ่นดินไหวขนาด 7.7 เกิดจากรอยเลื่อนสะกายในภาคกลางของเมียนมา เมื่อวันที่ 28 มีนาคม 2568 (USGS, 2025) ห่างจากกรุงเทพฯ ประมาณ 1,000 กม. แรงสั่นถูกขยายในชั้นดินเหนียวอ่อนของกรุงเทพฯ ทำให้อาคารสูงสั่นไหวอย่างรุนแรงและมีอาคารระหว่างก่อสร้างพังถล่ม ชั้นดินเหนียวอ่อนที่ถูกแรงสั่นซ้ำ ๆ อาจเกิดแรงดันน้ำส่วนเกินและยุบอัดเพิ่ม โครงงานนี้จึงทดสอบว่าอัตราการทรุดหลังเหตุการณ์เปลี่ยนไปหรือไม่'),
    H2('2.13', 'ข้อมูลประชากร อาคาร และสถานที่สำคัญแบบเปิด'),
    P('WorldPop (2025) ประมาณจำนวนประชากรรายช่อง 100 เมตรพร้อมโครงสร้างอายุและเพศ โดยกระจายประชากรเฉพาะในพื้นที่ที่มีอาคาร (constrained) Global Building Atlas (Zhu et al., 2025) ให้รูปร่างอาคารและความสูงทั่วโลกในรูปแบบ LoD1 ส่วน Overture Maps Foundation (2026) รวบรวมถนน ราง และสถานที่สำคัญจาก OpenStreetMap และแหล่งอื่นในรูปแบบมาตรฐานเดียวกัน'),
  ];
}

