// ------------------------------------------------------------------ สารบัญ
function tocPages() {
  const out = [front('สารบัญ', false), new Paragraph({ children: [new TextRun({ text: 'หน้า', font: L.FONT, size: L.SZ, bold: true })], alignment: AlignmentType.RIGHT })];
  for (const e of state.toc) out.push(tocLine(e.text, pg(e.key), e.level, e.level === 0));
  out.push(front('สารบัญตาราง', false), new Paragraph({ children: [new TextRun({ text: 'หน้า', font: L.FONT, size: L.SZ, bold: true })], alignment: AlignmentType.RIGHT }));
  for (const e of state.tables) out.push(tocLine(e.text, pg(e.key)));
  out.push(front('สารบัญรูป', false), new Paragraph({ children: [new TextRun({ text: 'หน้า', font: L.FONT, size: L.SZ, bold: true })], alignment: AlignmentType.RIGHT }));
  for (const e of state.figures) out.push(tocLine(e.text, pg(e.key)));
  return out;
}

